// Some portions generated by Co-Pilot
"use client";

import React, { useEffect, useState } from "react";
import { useLocale, useTranslations } from "next-intl";
import { fetchAvailableReleases } from "@/utils/fetchAvailableReleases";
import BarChart from "@/components/Dashboard/BarChart";
import LineChart from "@/components/Dashboard/LineChart";

interface SeriesType {
  name: string;
  data: (number | null)[];
  visible: boolean;
  type?: string;
}

type ArgsType = {
  visible: boolean;
  type: "daily" | "total";
  source?: string;
  feature_version: string;
  jvm_impl?: string;
};

type MonthlyArgsType = {
  type: "monthly" | "total";
  source?: string;
  feature_version: string;
  jvm_impl?: string;
};

const defaultArgs: ArgsType = {
  visible: true,
  type: "daily",
  feature_version: "",
};
const defaultArgs2: ArgsType = {
  visible: false,
  type: "daily",
  feature_version: "",
};
const defaultMonthlyArgs: MonthlyArgsType = {
  type: "monthly",
  feature_version: "",
};

function parseMonth(month: string, locale: string) {
  const [year, value] = month.split("-").map(Number);
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(Date.UTC(year, value - 1, 1)));
}

function processData(
  data: Array<{ daily: number; total: number }>,
  type: "daily" | "total",
  visible: boolean,
  name: string,
): SeriesType {
  let typeData: (number | null)[] = [];
  switch (type) {
    case "daily":
      typeData = data.map(({ daily }) => daily);
      break;
    case "total":
      typeData = data.map(({ total }) => total);
      break;
  }
  return {
    name,
    data: typeData,
    visible: data.length !== 0 && visible,
    type: "line",
  };
}

function max(arr1: string[] = [], arr2: string[] = []) {
  return arr1.length > arr2.length ? arr1 : arr2;
}

function padArray(state: SeriesType, diff: number): SeriesType {
  return {
    ...state,
    data: Array(diff).fill(null).concat(state.data),
  };
}

function createSeries(
  series: SeriesType,
  series2: SeriesType,
): Highcharts.SeriesOptionsType[] {
  const s1 = { ...series, data: [...series.data] };
  const s2 = { ...series2, data: [...series2.data] };
  s1.data.splice(0, s1.data.lastIndexOf(null) + 1);
  s2.data.splice(0, s2.data.lastIndexOf(null) + 1);
  const diff = s1.data.length - s2.data.length;
  const arr: SeriesType[] =
    diff > 0
      ? [s1, padArray(s2, diff)]
      : diff < 0
        ? [padArray(s1, -diff), s2]
        : [s1, s2];
  return arr.map((s) => ({
    type: "line",
    name: s.name,
    data: s.data,
    visible: s.visible,
  })) as Highcharts.SeriesOptionsType[];
}

function NativeRadioGroup<T extends string | number | undefined>({
  name,
  value,
  options,
  onChange,
}: {
  name: string;
  value: T;
  options: { label: string; value: T }[];
  onChange: (v: T) => void;
}) {
  const checkedValue = value ?? "";
  return (
    <div className="flex flex-row gap-3 flex-wrap">
      {options.map((opt) => (
        <label
          key={String(opt.value)}
          className="flex cursor-pointer items-center gap-2 rounded-lg border border-white/10 px-3 py-2 text-sm text-grey has-checked:border-pink/30 has-checked:bg-pink/10 has-checked:text-white"
        >
          <input
            type="radio"
            name={name}
            value={String(opt.value)}
            checked={checkedValue === opt.value}
            onChange={() => onChange(opt.value)}
            className="h-4 w-4 accent-pink"
          />
          <span>{opt.label}</span>
        </label>
      ))}
    </div>
  );
}

function NativeCheckbox({
  checked,
  onChange,
  label,
}: {
  checked: boolean;
  onChange: (v: boolean) => void;
  label: string;
}) {
  return (
    <input
      type="checkbox"
      aria-label={label}
      checked={checked}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
        onChange(e.target.checked)
      }
      className="h-4 w-4 accent-pink"
    />
  );
}

function NativeSlider({
  value,
  min,
  max,
  onChange,
  onAfterChange,
  label,
}: {
  value: number;
  min: number;
  max: number;
  onChange: (v: number) => void;
  onAfterChange: () => void;
  label: string;
}) {
  return (
    <input
      type="range"
      aria-label={label}
      min={min}
      max={max}
      value={value}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) =>
        onChange(Number(e.target.value))
      }
      onMouseUp={onAfterChange}
      onTouchEnd={onAfterChange}
      onKeyUp={(event) => {
        if (
          [
            "ArrowLeft",
            "ArrowRight",
            "ArrowUp",
            "ArrowDown",
            "Home",
            "End",
            "PageUp",
            "PageDown",
          ].includes(event.key)
        )
          onAfterChange();
      }}
      className="h-2 w-full rounded-lg bg-white/10 accent-pink"
    />
  );
}

function NativeSpinner() {
  const t = useTranslations("ModernPages.common");
  return (
    <div className="flex h-full items-center justify-center" role="status">
      <svg
        className="h-6 w-6 animate-spin text-pink"
        aria-hidden="true"
        xmlns="http://www.w3.org/2000/svg"
        fill="none"
        viewBox="0 0 24 24"
      >
        <circle
          className="opacity-25"
          cx="12"
          cy="12"
          r="10"
          stroke="currentColor"
          strokeWidth="4"
        ></circle>
        <path
          className="opacity-75"
          fill="currentColor"
          d="M4 12a8 8 0 018-8v8z"
        ></path>
      </svg>
      <span className="ml-2 text-grey">{t("loading")}</span>
    </div>
  );
}

interface FiltersBoxProps<T extends ArgsType | MonthlyArgsType> {
  argsObj: T;
  setArgsObj: React.Dispatch<React.SetStateAction<T>>;
  versions: number[] | undefined;
  isMonthly?: boolean;
  groupId: string;
}

function FiltersBox<T extends ArgsType | MonthlyArgsType>({
  argsObj,
  setArgsObj,
  versions,
  isMonthly = false,
  groupId,
}: FiltersBoxProps<T>) {
  const t = useTranslations("ModernPages.stats");
  const tCommon = useTranslations("ModernPages.common");
  const sourceOptions = [
    { label: tCommon("all"), value: "" },
    { label: "GitHub", value: "github" },
    { label: "Docker", value: "dockerhub" },
  ];
  const typeOptions = [
    {
      label: t(isMonthly ? "monthly-label" : "daily-label"),
      value: isMonthly ? "monthly" : "daily",
    },
    { label: t("total-label"), value: "total" },
  ];
  const generateVersions = () => {
    const versionOpts: { label: string; value: string }[] = [
      { label: tCommon("all"), value: "" },
    ];
    if (versions) {
      for (const version of versions) {
        versionOpts.push({ label: "JDK " + version, value: String(version) });
      }
    }
    return versionOpts;
  };

  function hasVisible(obj: ArgsType | MonthlyArgsType): obj is ArgsType {
    return Object.prototype.hasOwnProperty.call(obj, "visible");
  }

  return (
    <fieldset className="min-w-0 rounded-xl border border-white/10 bg-[#10052d] p-4">
      <legend className="px-2 text-sm font-medium text-[#ff91b7]">
        {isMonthly ? t("monthly") : t("series", { number: groupId })}
      </legend>
      <div className="grid items-start gap-5 lg:grid-cols-[1.4fr_1fr_auto_1fr]">
        <fieldset className="min-w-0">
          <legend className="mb-2 text-xs font-medium text-grey">
            {t("source")}
          </legend>
          <NativeRadioGroup
            name={`source-${groupId}`}
            value={argsObj.source ?? ""}
            options={sourceOptions}
            onChange={(v: string) =>
              setArgsObj((prev) => ({
                ...prev,
                source: v === "" ? undefined : v,
              }))
            }
          />
        </fieldset>
        <div className="flex min-w-0 flex-col gap-1">
          <label
            htmlFor={`feature-version-${groupId}`}
            className="mb-2 text-xs font-medium text-grey"
          >
            {t("version")}
          </label>
          <select
            id={`feature-version-${groupId}`}
            className="min-h-10 rounded-lg border border-white/15 bg-[#1c1040] px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-pink"
            value={argsObj.feature_version}
            onChange={(event) =>
              setArgsObj((prev) => ({
                ...prev,
                feature_version: event.target.value,
              }))
            }
          >
            {generateVersions().map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>
        {hasVisible(argsObj) && (
          <div className="flex flex-col gap-1">
            <span className="mb-2 text-xs font-medium text-grey">
              {t("visible")}
            </span>
            <NativeCheckbox
              label={t("visible")}
              checked={argsObj.visible}
              onChange={(v: boolean) =>
                setArgsObj((prev) => ({
                  ...prev,
                  visible: v,
                }))
              }
            />
          </div>
        )}
        <fieldset className="min-w-0">
          <legend className="mb-2 text-xs font-medium text-grey">
            {t("type")}
          </legend>
          <NativeRadioGroup
            name={`type-${groupId}`}
            value={argsObj.type}
            options={typeOptions}
            onChange={(v: string) =>
              setArgsObj((prev) => ({
                ...prev,
                type: v,
              }))
            }
          />
        </fieldset>
      </div>
    </fieldset>
  );
}

const DownloadTrendsPage: React.FC = () => {
  const t = useTranslations("ModernPages.stats");
  const locale = useLocale();
  const [series, setSeries] = useState<SeriesType | undefined>();
  const [series2, setSeries2] = useState<SeriesType | undefined>();
  const [monthlyData, setMonthlyData] = useState<
    Record<string, number> | undefined
  >();
  const [categories, setCategories] = useState<string[] | undefined>();
  const [categories2, setCategories2] = useState<string[] | undefined>();
  const [args, setArgs] = useState<ArgsType>({ ...defaultArgs });
  const [args2, setArgs2] = useState<ArgsType>({ ...defaultArgs2 });
  const [monthlyArgs, setMonthlyArgs] = useState<MonthlyArgsType>({
    ...defaultMonthlyArgs,
  });
  const [days, setDays] = useState<number>(30);
  const [versions, setVersions] = useState<number[] | undefined>();
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      setLoading(true);
      const releases = await fetchAvailableReleases();
      setVersions(releases.available_releases);
      await updateData(1, args);
      await updateData(2, args2);
      await updateMonthlyData(monthlyArgs);
      setLoading(false);
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!loading) updateData(1, args);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [args]);

  useEffect(() => {
    if (!loading) updateData(2, args2);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [args2]);

  useEffect(() => {
    if (!loading) updateMonthlyData(monthlyArgs);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [monthlyArgs]);

  async function updateData(seriesID: number, argsObj: ArgsType) {
    const params = generateParams(argsObj);
    const data = await fetchTracking(params);
    if (!data) return;
    if (seriesID === 1) {
      setSeries(
        processData(
          data,
          argsObj.type,
          argsObj.visible,
          t("series", { number: 1 }),
        ),
      );
      setCategories(data.map(({ date }: { date: string }) => formatDate(date)));
    } else {
      setSeries2(
        processData(
          data,
          argsObj.type,
          argsObj.visible,
          t("series", { number: 2 }),
        ),
      );
      setCategories2(
        data.map(({ date }: { date: string }) => formatDate(date)),
      );
    }
  }

  async function updateMonthlyData(argsObj: MonthlyArgsType) {
    const params = generateParams(argsObj);
    const data: Array<{ month: string; monthly: number; total: number }> =
      await fetchMonthly(params);
    if (!data) return;
    const monthly: Record<string, number> = {};
    data.forEach((d) => {
      monthly[parseMonth(d.month, locale)] =
        argsObj.type === "monthly" ? d.monthly : d.total;
    });
    setMonthlyData(monthly);
  }

  function generateParams(argsObj: ArgsType | MonthlyArgsType) {
    return {
      source: argsObj.source || undefined,
      feature_version:
        argsObj.feature_version !== ""
          ? Number(argsObj.feature_version)
          : undefined,
      jvm_impl: argsObj.jvm_impl || undefined,
      days,
    };
  }

  function formatDate(date: string) {
    const d = new Date(date);
    return d.toLocaleDateString(locale);
  }

  async function fetchTracking(
    params: Record<string, string | number | undefined>,
  ) {
    const url = new URL(
      "https://api.adoptium.net/v3/stats/downloads/tracking/",
    );
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined) url.searchParams.append(key, String(value));
    });
    const res = await fetch(url.toString());
    if (!res.ok) return [];
    return res.json() as Promise<
      Array<{ date: string; daily: number; total: number }>
    >;
  }
  async function fetchMonthly(
    params: Record<string, string | number | undefined>,
  ) {
    const url = new URL("https://api.adoptium.net/v3/stats/downloads/monthly/");
    Object.entries(params).forEach(([key, value]) => {
      if (value !== undefined) url.searchParams.append(key, String(value));
    });
    const res = await fetch(url.toString());
    if (!res.ok) return [];
    return res.json() as Promise<
      Array<{ month: string; monthly: number; total: number }>
    >;
  }

  return (
    <div
      className="mx-auto max-w-7xl space-y-6 px-6 py-8 sm:px-8"
      aria-busy={loading}
    >
      <section className="min-w-0 rounded-2xl border border-white/10 bg-white/[0.025] p-4 sm:p-6">
        <div className="h-[400px] min-w-0">
          {loading ? (
            <NativeSpinner />
          ) : (
            <LineChart
              series={series && series2 ? createSeries(series, series2) : []}
              categories={max(categories, categories2)}
              name={t("daily")}
            />
          )}
        </div>
        <fieldset disabled={loading} className="mt-6 grid min-w-0 gap-4">
          <FiltersBox
            argsObj={args}
            setArgsObj={setArgs}
            versions={versions}
            groupId="1"
          />
          <FiltersBox
            argsObj={args2}
            setArgsObj={setArgs2}
            versions={versions}
            groupId="2"
          />
          <div className="rounded-xl border border-white/10 p-4">
            <div className="mb-3 text-sm text-grey">
              {t("days")}: <output className="text-white">{days}</output>
            </div>
            <NativeSlider
              label={t("days")}
              value={days}
              max={180}
              min={1}
              onChange={setDays}
              onAfterChange={() => {
                updateData(1, args);
                updateData(2, args2);
              }}
            />
          </div>
        </fieldset>
      </section>
      <section className="min-w-0 rounded-2xl border border-white/10 bg-white/[0.025] p-4 sm:p-6">
        <div className="h-[400px] min-w-0">
          {loading ? (
            <div
              className="h-full animate-pulse rounded-xl bg-white/[0.025] motion-reduce:animate-none"
              aria-hidden="true"
            />
          ) : (
            <BarChart data={monthlyData || {}} name={t("monthly")} />
          )}
        </div>
        <fieldset disabled={loading} className="mt-6 min-w-0">
          <FiltersBox
            argsObj={monthlyArgs}
            setArgsObj={setMonthlyArgs}
            versions={versions}
            isMonthly
            groupId="monthly"
          />
        </fieldset>
      </section>
      <p className="text-xs leading-relaxed text-grey">{t("docker-note")}</p>
    </div>
  );
};

export default DownloadTrendsPage;
